/// <summary>
/// class <c>METTelemetrySOTMSShipmentInfoEvent</c> is used to log event whenever sales order is TMS shipment created.
/// </summary>
internal final class METTelemetrySOTMSShipmentInfoEvent extends ISMTelemetryBase
{
}

Method.Source:
/// <summary>
/// Initialize the class <c>METTelemetrySOTMSShipmentInfoEvent</c>
/// </summary>
/// <returns> Instance of class <c>METTelemetrySOTMSShipmentInfoEvent</c> </returns>
public static METTelemetrySOTMSShipmentInfoEvent construct()
{
    return new METTelemetrySOTMSShipmentInfoEvent();
}

/// <summary>
/// if the log level is set to information it will log the request and response data as wekk as there is an error
/// </summary>
/// <returns> a boolean value </returns>
protected boolean shouldLogEvent()
{
    return true;
}

/// <summary>
/// Run transfer order telmetry log
/// </summary>
/// <param name = "_salesId"> table <c>SalesId</c> </param>
public static void runTelemetryEvent(SalesId _salesId)
{
    METTelemetrySOTMSShipmentInfoEvent tmsShipmentInfo = METTelemetrySOTMSShipmentInfoEvent::construct();

    tmsShipmentInfo.addRunTimePropertyToAppinsights(_salesId);

    tmsShipmentInfo.processEvent(METTelemetryEventNames::SOTMSEngineInfoEvent);
}

/// <summary>
/// Add runtime telemetry property to application insights.
/// </summary>
/// <param name = "_salesID"> sales id</c> </param>
public void addRunTimePropertyToAppinsights(SalesId _salesID)
{
    SalesTable salesTable = SalesTable::find(_salesID);
    METSalesTable metSalestable = METSalesTable::findBySalesTable(salesTable.RecId);

    this.addRuntimeProperty('salesOrderNumber', salesTable.SalesId);
    this.addRuntimeProperty('warehouseId' ,salesTable.InventLocationId);
    this.addRuntimeProperty('orderReferenceNumber', salesTable.CustomerRef);
    this.addRuntimeProperty('industryKey', metSalestable.IndustryKey);
    this.addRuntimeProperty('metcashSalesOrderType', salesTable.METSalesOrderType);
    this.addRuntimeProperty('customerNumber', salesTable.CustAccount);
    this.addRuntimeProperty('transmissionNumber', metSalestable.TransmissionNumber);
}
